# %% ../nbs/02_ssp_interpolation.ipynb 3
import numpy as np

# %% ../nbs/02_ssp_interpolation.ipynb 4
def ssp_grid_weights(age_hydro:np.array=None, # Ages of the HACC stellar particles (Gyr)
                     metal_hydro:np.array=None, # Metallicities of the stellar particles (Z/Zsun)
                     age_fsps:np.array=None, # Ages in SPS library (Gyr)
                     z_padova_fsps:np.array=None, # Metallicities in SPS library (Z/Zsun)
                    )-> tuple: # Lower metallicity index, lower age index, fractional metallicity offset, fractional age offset
    '''
    Bilinear-interpolation bracket of each particle on the SSP grid.

    The library grid is logarithmic in both age (0.05 dex steps) and
    metallicity, so interpolate in (log age, log Z). Particles outside the
    grid are clipped to its edge: the hydro metallicities reach several
    Zsun while the Padova grid stops at 1.58 Zsun (~30% of z=0 particles),
    and extrapolating SSPs linearly produces negative fluxes.
    '''
    log_age_grid, log_met_grid = np.log10(age_fsps), np.log10(z_padova_fsps)
    tiny = 1e-12
    log_age = np.clip(np.log10(np.maximum(age_hydro, tiny)), log_age_grid[0], log_age_grid[-1])
    log_met = np.clip(np.log10(np.maximum(metal_hydro, tiny)), log_met_grid[0], log_met_grid[-1])

    age_index = np.clip(np.searchsorted(log_age_grid, log_age) - 1, 0, log_age_grid.shape[0] - 2)
    met_index = np.clip(np.searchsorted(log_met_grid, log_met) - 1, 0, log_met_grid.shape[0] - 2)

    age_frac = (log_age - log_age_grid[age_index])/(log_age_grid[age_index + 1] - log_age_grid[age_index])
    met_frac = (log_met - log_met_grid[met_index])/(log_met_grid[met_index + 1] - log_met_grid[met_index])

    return met_index, age_index, met_frac, age_frac

# %% ../nbs/02_ssp_interpolation.ipynb 5
def spec_ssp_lookup_nearest(age_hydro_i:np.float32=None, # Age of the HACC stellar particle
             metal_hydro_i:np.float32=None, # Metallicity of the stellar particle
             mass_hydro_i:np.float32=None, # Mass *formed* of the stellar particle (initial mass)
             age_fsps:np.float32=None, # Ages in SPS library
             z_padova_fsps:np.float32=None, # Metallicities in SPS library
             spec_flux:np.array=None, # Stellar library SEDs
             spec_wave:np.array=None, # Stellar library wavelengths
            )-> tuple: # SSP Wavelength (A), SSP Luminosity (Lsun/A)
    '''
    Lookup table for finding the closest SPS entry to HACC SSP
    '''
    # https://ned.ipac.caltech.edu/level5/Sept14/Conroy/Conroy2.html

    age_index = np.argmin(np.abs(np.log10(age_fsps)-np.log10(np.maximum(age_hydro_i, 1e-12))))
    met_index = np.argmin(np.abs(np.log10(z_padova_fsps)-np.log10(np.maximum(metal_hydro_i, 1e-12))))
    spec_flux_i = mass_hydro_i*spec_flux[met_index, age_index]

    return spec_wave, spec_flux_i

# %% ../nbs/02_ssp_interpolation.ipynb 6
def spec_ssp_lookup(age_hydro_i:np.float32=None, # Age of the HACC stellar particle
             metal_hydro_i:np.float32=None, # Metallicity of the stellar particle
             mass_hydro_i:np.float32=None, # Mass *formed* of the stellar particle (initial mass)
             age_fsps:np.float32=None, # Ages in SPS library
             z_padova_fsps:np.float32=None, # Metallicities in SPS library
             spec_flux:np.array=None, # Stellar library SEDs
             spec_wave:np.array=None, # Stellar library wavelengths
            )-> tuple: # SSP Wavelength (A), SSP Luminosity (Lsun/A)
    '''
    Bilinear interpolation (in log age, log Z) of the SPS library at one HACC SSP.

    The library is per unit solar mass *formed*, so the weight should be the
    particle's initial mass, not its current (mass-loss reduced) one.
    '''
    # https://ned.ipac.caltech.edu/level5/Sept14/Conroy/Conroy2.html

    met_min, age_min, met_frac, age_frac = ssp_grid_weights(age_hydro_i, metal_hydro_i, age_fsps, z_padova_fsps)

    spec_flux_i = ((1 - met_frac)*(1 - age_frac)*spec_flux[met_min, age_min]
                   + (1 - met_frac)*age_frac*spec_flux[met_min, age_min + 1]
                   + met_frac*(1 - age_frac)*spec_flux[met_min + 1, age_min]
                   + met_frac*age_frac*spec_flux[met_min + 1, age_min + 1])

    spec_flux_i_mass_weighted = mass_hydro_i*spec_flux_i

    return spec_wave, spec_flux_i_mass_weighted

# %% ../nbs/02_ssp_interpolation.ipynb 7
def spec_ssp_lookup_many(age_hydro:np.array=None, # Ages of the HACC stellar particles (Gyr)
             metal_hydro:np.array=None, # Metallicities of the stellar particles (Z/Zsun)
             mass_hydro:np.array=None, # Masses *formed* of the stellar particles (initial mass)
             age_fsps:np.float32=None, # Ages in SPS library
             z_padova_fsps:np.float32=None, # Metallicities in SPS library
             spec_flux:np.array=None, # Stellar library SEDs
             spec_wave:np.array=None, # Stellar library wavelengths
            )-> tuple: # SSP Wavelength (A), SSP Luminosities (Lsun/A), shape (n_particles, n_wave)
    '''
    `spec_ssp_lookup` for all particles at once (no python loop)
    '''
    met_min, age_min, met_frac, age_frac = ssp_grid_weights(np.atleast_1d(age_hydro), np.atleast_1d(metal_hydro), age_fsps, z_padova_fsps)
    mass_hydro = np.atleast_1d(mass_hydro)

    spec_flux_all = np.zeros(shape=(mass_hydro.shape[0], spec_wave.shape[0]))
    for d_met, w_met in ((0, 1 - met_frac), (1, met_frac)):
        for d_age, w_age in ((0, 1 - age_frac), (1, age_frac)):
            spec_flux_all += (mass_hydro*w_met*w_age)[:, None]*spec_flux[met_min + d_met, age_min + d_age]

    return spec_wave, spec_flux_all


def ssp_weight_grid(age_hydro:np.array=None, # Ages of the HACC stellar particles (Gyr)
             metal_hydro:np.array=None, # Metallicities of the stellar particles (Z/Zsun)
             mass_hydro:np.array=None, # Masses *formed* of the stellar particles (initial mass)
             age_fsps:np.float32=None, # Ages in SPS library
             z_padova_fsps:np.float32=None, # Metallicities in SPS library
            )-> np.array: # Mass formed deposited on each library node, shape (n_metal, n_age)
    '''
    Deposit the particles onto the (metallicity, age) library grid with
    bilinear weights. The CSP is then a single contraction,
    `np.tensordot(weights, spec_flux, axes=([0, 1], [0, 1]))`, identical to
    summing `spec_ssp_lookup` over particles but independent of their number.
    '''
    met_min, age_min, met_frac, age_frac = ssp_grid_weights(np.atleast_1d(age_hydro), np.atleast_1d(metal_hydro), age_fsps, z_padova_fsps)
    n_met, n_age = z_padova_fsps.shape[0], age_fsps.shape[0]

    weights = np.zeros(n_met*n_age)
    for d_met, w_met in ((0, 1 - met_frac), (1, met_frac)):
        for d_age, w_age in ((0, 1 - age_frac), (1, age_frac)):
            weights += np.bincount((met_min + d_met)*n_age + age_min + d_age, weights=mass_hydro*w_met*w_age, minlength=n_met*n_age)

    return weights.reshape(n_met, n_age)

# %% ../nbs/02_ssp_interpolation.ipynb 9
def smooth_particle_sfh(age_hydro:np.array=None, # Ages of the stellar particles of ONE galaxy (Gyr)
                        n_sub:int=16, # Number of sub-particles each particle is split into
                        max_age_gyr:np.float32=13.8, # Upper limit on the smoothed ages
                       )-> np.array: # Sub-particle ages, shape (n_particles, n_sub); each carries 1/n_sub of the particle mass
    '''
    Spread each star particle uniformly over the age interval it samples
    (mid-points to its neighbours in age). Metallicity and mass are untouched:
    sub-particle k of particle i has metallicity Z_i and mass m_i/n_sub.
    '''
    age_hydro = np.atleast_1d(np.asarray(age_hydro, dtype=float))
    if age_hydro.shape[0] < 2 or n_sub < 2:
        return np.repeat(age_hydro[:, None], max(n_sub, 1), axis=1)

    order = np.argsort(age_hydro)
    age_sorted = age_hydro[order]
    mid = 0.5*(age_sorted[1:] + age_sorted[:-1])
    lower = np.concatenate([[max(0.0, 2*age_sorted[0] - mid[0])], mid])
    upper = np.concatenate([mid, [min(max(max_age_gyr, age_sorted[-1]), 2*age_sorted[-1] - mid[-1])]])

    frac = (np.arange(n_sub) + 0.5)/n_sub
    age_sub = np.empty((age_hydro.shape[0], n_sub))
    age_sub[order] = lower[:, None] + frac[None, :]*(upper - lower)[:, None]
    return age_sub
